contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: receiver and amount to forward to c.sendTo. Payable so test can fund transfers if needed.
    function run(address receiver, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");

        // First attempt as owner (this contract). Must observe whether it reverts.
        bool firstReverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Second attempt as owner to check owner ability is preserved.
        bool secondReverted;
        c.sendTo(receiver, 0); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General rule: when this contract (the deployer/owner) calls sendTo, the call must not permanently lose the ability
        // to call again: i.e., if the first call succeeded then the second must also succeed; and if the first failed then
        // the second must also fail (consistent ownership check). This enforces that ownership-based access does not flip
        // between calls unexpectedly.
        assert((!firstReverted && !secondReverted) || (firstReverted && secondReverted));
    }

    receive() external payable {}
}

